1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Canonical identity of an owner for duplicate detection. All duplicate detection is
10	 * consolidated into this single derived key
11	 * {@code identityKey = normalizedTelephone + '|' + (email or empty) + '|' + householdId}: two
12	 * owners are duplicates only when their whole keys are equal.
13	 *
14	 * <p>A person is individuated by their telephone (and email): a re-registration reusing a
15	 * telephone is a duplicate regardless of address, while two members of one household with
16	 * different telephones have different keys and are both allowed. The household therefore does
17	 * not participate in a person's identity, so the {@code householdId} component of the key is
18	 * empty — it is kept in the key's shape for the fixed format above. (The owner's stored
19	 * {@code householdId} — the SHA of last name and address — is a separate concern used for
20	 * household sizing, see {@link AssignHouseholdId} and {@link CountHouseholdMembers}.)
21	 *
22	 * <p>Telephone is canonicalized with {@link TelephoneNormalizer#toE164(String)} and email is
23	 * lower-cased, so the key is computed identically for an incoming request and an already-stored
24	 * owner regardless of incidental formatting differences.
25	 */
26	final class OwnerIdentity {
27	
28	    private OwnerIdentity() {
29	    }
30	
31	    /** Identity key of a create request. */
32	    static String of(OwnerFieldsDto request) {
33	        return of(request.getTelephone(), request.getEmail());
34	    }
35	
36	    /** Identity key of an existing owner. */
37	    static String of(Owner owner) {
38	        return of(owner.getTelephone(), owner.getEmail());
39	    }
40	
41	    private static String of(String telephone, String email) {
42	        String normalizedTelephone = TelephoneNormalizer.toE164(telephone);
43	        String normalizedEmail = (email == null) ? "" : email.trim().toLowerCase(Locale.ROOT);
44	        // householdId component is empty: a household does not individuate a person (see class doc).
45	        return (normalizedTelephone == null ? "" : normalizedTelephone) + '|' + normalizedEmail + '|';
46	    }
47	}
