3	import java.util.Map;
4	
5	/**
6	 * Resolves an owner's locality (canonical region) from their city using a fixed
7	 * city-to-region table. Cities that are not in the table resolve to {@link #UNKNOWN}.
8	 */
9	public final class CityRegions {
10	
11	    /** Locality returned for any city not present in {@link #CITY_TO_REGION}. */
12	    public static final String UNKNOWN = "UNKNOWN";
13	
14	    /** Fixed, canonical city-to-region mapping. */
15	    private static final Map<String, String> CITY_TO_REGION = Map.of(
16	            "Sydney", "NSW",
17	            "Melbourne", "VIC",
18	            "Brisbane", "QLD");
19	
20	    private CityRegions() {
21	    }
22	
23	    /**
24	     * Return the canonical region for {@code city}, or {@link #UNKNOWN} when the city is
25	     * absent from the table.
26	     */
27	    public static String localityOf(String city) {
28	        return CITY_TO_REGION.getOrDefault(city, UNKNOWN);
29	    }
30	}
