1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Validates an owner's 4-digit postcode against the postcode range of their city's region.
8	 * Ranges are keyed by the canonical region resolved via {@link CityRegions}; a city whose
9	 * region is {@link CityRegions#UNKNOWN} has no range and accepts any well-formed 4-digit
10	 * postcode.
11	 */
12	public final class Postcodes {
13	
14	    /** A well-formed postcode is exactly four digits. */
15	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
16	
17	    /** Region -> inclusive 4-digit postcode range {low, high}. */
18	    private static final Map<String, int[]> REGION_RANGE = Map.of(
19	            "NSW", new int[] {2000, 2099},
20	            "VIC", new int[] {3000, 3099},
21	            "QLD", new int[] {4000, 4099});
22	
23	    private Postcodes() {
24	    }
25	
26	    /** Whether {@code postcode} is exactly four digits. */
27	    public static boolean isWellFormed(String postcode) {
28	        return postcode != null && FOUR_DIGITS.matcher(postcode).matches();
29	    }
30	
31	    /**
32	     * The canonical region whose postcode range contains {@code postcode}, or {@code null} when
33	     * the postcode is absent, malformed, or falls in no known range.
34	     */
35	    public static String regionOf(String postcode) {
36	        if (!isWellFormed(postcode)) {
37	            return null;
38	        }
39	        int value = Integer.parseInt(postcode);
40	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
41	            int[] range = entry.getValue();
42	            if (value >= range[0] && value <= range[1]) {
43	                return entry.getKey();
44	            }
45	        }
46	        return null;
47	    }
48	
49	    /**
50	     * Derive an owner's locality (canonical region), preferring the postcode: use the region whose
51	     * range contains {@code postcode}, falling back to the {@code city}-to-region table (see
52	     * {@link CityRegions}) when the postcode is absent or in no known range.
53	     */
54	    public static String localityOf(String city, String postcode) {
55	        String region = regionOf(postcode);
56	        return region != null ? region : CityRegions.localityOf(city);
57	    }
58	
59	    /**
60	     * Whether {@code postcode} is valid for {@code city}: it must be four digits and, when the
61	     * city's region has a known range, fall within it. A city with no known region accepts any
62	     * four-digit postcode.
63	     */
64	    public static boolean isValidForCity(String city, String postcode) {
65	        if (!isWellFormed(postcode)) {
66	            return false;
67	        }
68	        int[] range = REGION_RANGE.get(CityRegions.localityOf(city));
69	        if (range == null) {
70	            return true;
71	        }
72	        int value = Integer.parseInt(postcode);
73	        return value >= range[0] && value <= range[1];
74	    }
75	}
