1	package org.springframework.samples.petclinic.util;
2	
3	/**
4	 * Computes the Luhn check digit over the decimal digits contained in a string. Non-digit
5	 * characters are ignored, so a formatted code such as a customer code ('SYD-SMI-0007') is
6	 * reduced to its digits before the standard Luhn algorithm is applied: working right to
7	 * left, every second digit is doubled (subtracting 9 when the result exceeds 9), the digits
8	 * are summed and the check digit is the amount needed to round the sum up to a multiple of 10.
9	 */
10	public final class Luhn {
11	
12	    private Luhn() {
13	    }
14	
15	    /** The Luhn check digit (0-9) over the decimal digits contained in {@code s}. */
16	    public static int checkDigit(String s) {
17	        int sum = 0;
18	        boolean doubleDigit = true;
19	        for (int i = s.length() - 1; i >= 0; i--) {
20	            char c = s.charAt(i);
21	            if (c < '0' || c > '9') {
22	                continue;
23	            }
24	            int d = c - '0';
25	            if (doubleDigit) {
26	                d *= 2;
27	                if (d > 9) {
28	                    d -= 9;
29	                }
30	            }
31	            sum += d;
32	            doubleDigit = !doubleDigit;
33	        }
34	        return (10 - (sum % 10)) % 10;
35	    }
36	}
