1	package org.springframework.samples.petclinic.util;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's numeric membership level. The level starts at {@link #BASE} and
7	 * gains a point for a present email and a point for having no namesakes
8	 * ({@code namesakeCount} is 0), capped at {@link #MAX} (level 4 is reserved for tenure).
9	 */
10	public final class MembershipLevels {
11	
12	    /** Level every owner starts at. */
13	    public static final int BASE = 1;
14	
15	    /** Highest level derivable here; level 4 is reserved for tenure. */
16	    public static final int MAX = 3;
17	
18	    private MembershipLevels() {
19	    }
20	
21	    /** Return the membership level (1 to 3) for {@code owner}. */
22	    public static int of(Owner owner) {
23	        int level = BASE;
24	        if (owner.hasEmail()) {
25	            level++;
26	        }
27	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
28	            level++;
29	        }
30	        return Math.min(level, MAX);
31	    }
32	}
