7	/**
8	 * Normalizes the telephone on a create request to E.164 form (see {@link TelephoneNormalizer}).
9	 * Stores the E.164 value back on the request (mutating the shared {@code @Val} object) so
10	 * {@link BuildOwner} and the response carry it; rejects with {@link InvalidTelephoneException}
11	 * (400) when the number cannot form valid E.164 or its national-number length is wrong for the
12	 * country code (see {@link E164CountryLength}). Runs after {@link ValidateNewOwner} has
13	 * confirmed the field is present.
14	 */
15	public class NormalizeOwnerTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
18	        String raw = request.getTelephone();
19	        String e164 = TelephoneNormalizer.toE164(raw);
20	        if (e164 == null || !E164CountryLength.isNationalLengthValid(e164)) {
21	            throw new InvalidTelephoneException(raw);
22	        }
23	        request.setTelephone(e164);
24	    }
25	}
