1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Canonical key identifying a household by its owner's last name and address. Two owners
10	 * belong to the same household when their keys are equal: last name and address are compared
11	 * case-insensitively with leading/trailing and repeated whitespace collapsed to a single
12	 * space, so incidental formatting differences do not hide a match.
13	 */
14	final class HouseholdKey {
15	
16	    private HouseholdKey() {
17	    }
18	
19	    static String of(String lastName, String address) {
20	        return normalize(lastName) + '�' + normalize(address);
21	    }
22	
23	    /**
24	     * Stable identifier shared by every owner of a household: the SHA-256 hex digest of the
25	     * canonical {@link #of(String, String) key}. Purely derived from last name and address, so
26	     * two owners in the same household always get the same value regardless of creation order.
27	     */
28	    static String id(String lastName, String address) {
29	        byte[] digest;
30	        try {
31	            digest = MessageDigest.getInstance("SHA-256")
32	                    .digest(of(lastName, address).getBytes(StandardCharsets.UTF_8));
33	        }
34	        catch (NoSuchAlgorithmException ex) {
35	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
36	        }
37	        StringBuilder hex = new StringBuilder(digest.length * 2);
38	        for (byte b : digest) {
39	            hex.append(Character.forDigit((b >> 4) & 0xF, 16));
40	            hex.append(Character.forDigit(b & 0xF, 16));
41	        }
42	        return hex.toString();
43	    }
44	
45	    private static String normalize(String value) {
46	        if (value == null) {
47	            return "";
48	        }
49	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
50	    }
51	}
