3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Registration-date business rules shared by the owner-create pipeline. A registration
8	 * date must fall on a business day: when it lands on a Saturday or Sunday it rolls forward
9	 * to the next Monday. This applies to the effective date whether it was supplied on the
10	 * request or defaulted to the server's current date, so both the step that stores the date
11	 * ({@link ResolveRegistrationDate}) and the daily-limit guard ({@link EnsureDailyLimit})
12	 * derive the same adjusted day from here.
13	 */
14	final class RegistrationDates {
15	
16	    private RegistrationDates() {
17	    }
18	
19	    /** Roll a weekend date forward to the following Monday; a weekday is returned unchanged. */
20	    static LocalDate toBusinessDay(LocalDate date) {
21	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
22	            date = date.plusDays(1);
23	        }
24	        return date;
25	    }
26	
27	    /**
28	     * The effective registration date: the supplied date, or the server's current date when
29	     * none was supplied, in either case rolled forward onto a business day.
30	     */
31	    static LocalDate effective(LocalDate supplied) {
32	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
33	    }
34	}
