9	/**
10	 * Rejects a create request whose derived {@link OwnerIdentity identity key} exactly matches an
11	 * existing owner's, so the pair maps to a 409. This is the single duplicate check for owner
12	 * creation, consolidating the former separate telephone, email and household guards: only an
13	 * exact whole-key match is a duplicate, so two members of the same household with different
14	 * telephones (different keys) are both allowed.
15	 *
16	 * <p>Runs after the request's telephone and email have been normalized, and before
17	 * {@link BuildOwner} maps it to an entity. Existing owners are compared on their recomputed key
18	 * too, so formatting differences do not hide a collision.
19	 */
20	public class EnsureUniqueIdentity {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DuplicateIdentityException {
24	        String identityKey = OwnerIdentity.of(request);
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (identityKey.equals(OwnerIdentity.of(existing))) {
27	                throw new DuplicateIdentityException(identityKey);
28	            }
29	        }
30	    }
31	}
