3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Shared address normalization: trims and collapses runs of whitespace to a single space,
8	 * upper-cases, and expands common street-type abbreviations token by token (ST -> STREET,
9	 * RD -> ROAD, AVE -> AVENUE). Used both to canonicalize an incoming request's address (the
10	 * stored and returned form) and to compare it against the addresses already held on other
11	 * owners, so incidental formatting or abbreviation differences do not hide a match.
12	 */
13	final class AddressNormalizer {
14	
15	    private static final Map<String, String> ABBREVIATIONS = Map.of(
16	            "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
17	
18	    private AddressNormalizer() {
19	    }
20	
21	    /**
22	     * Returns the normalized form of {@code raw}: upper-case, single-spaced tokens with known
23	     * abbreviations expanded. A {@code null} address yields an empty string, so a value that is
24	     * blank after normalization is detectable as blank.
25	     */
26	    static String normalize(String raw) {
27	        if (raw == null || raw.isBlank()) {
28	            return "";
29	        }
30	        StringBuilder normalized = new StringBuilder();
31	        for (String token : raw.trim().split("\\s+")) {
32	            String upper = token.toUpperCase(Locale.ROOT);
33	            if (normalized.length() > 0) {
34	                normalized.append(' ');
35	            }
36	            normalized.append(ABBREVIATIONS.getOrDefault(upper, upper));
37	        }
38	        return normalized.toString();
39	    }
40	}
