import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Canonical key identifying a household by its owner's last name and address. Two owners
 * belong to the same household when their keys are equal: last name and address are compared
 * case-insensitively with leading/trailing and repeated whitespace collapsed to a single
 * space, so incidental formatting differences do not hide a match.
 */
final class HouseholdKey {

    private HouseholdKey() {
    }

    static String of(String lastName, String address) {
        return normalize(lastName) + '�' + normalize(address);
    }

    /**
     * Stable identifier shared by every owner of a household: the SHA-256 hex digest of the
     * canonical {@link #of(String, String) key}. Purely derived from last name and address, so
     * two owners in the same household always get the same value regardless of creation order.
     */
    static String id(String lastName, String address) {
        byte[] digest;
        try {
            digest = MessageDigest.getInstance("SHA-256")
                    .digest(of(lastName, address).getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(Character.forDigit((b >> 4) & 0xF, 16));
            hex.append(Character.forDigit(b & 0xF, 16));
        }
        return hex.toString();
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

