 * place.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        String region = Postcodes.regionCode(owner.getPostcode());
        owner.setCustomerCode(CustomerCode.of(region, owner.getTelephone(), owner.getLastName()));
    }
}

